// First 8 days of a month: re-pull the whole previous month so late conversions
// (7-day click attribution) are final. After that: month-to-date.
const until = $today.minus({ days: 1 });
const monthStart = $today.startOf('month');
const since = $today.day <= 8 ? monthStart.minus({ months: 1 }) : monthStart;
return [{ json: { since: since.toISODate(), until: until.toISODate(), time_range: JSON.stringify({ since: since.toISODate(), until: until.toISODate() }) } }];

const CONFIG={purchase:['offsite_conversion.fb_pixel_purchase','omni_purchase','purchase'],purchase_value:['offsite_conversion.fb_pixel_purchase','omni_purchase','purchase'],atc:['offsite_conversion.fb_pixel_add_to_cart','omni_add_to_cart','add_to_cart'],ic:['offsite_conversion.fb_pixel_initiate_checkout','omni_initiated_checkout','initiate_checkout'],lpv:['landing_page_view']};
function num(v){if(v==null||v==='')return 0;const n=Number(v);return Number.isFinite(n)?n:0;}
function actionSum(arr,types){if(!Array.isArray(arr))return 0;let t=0;for(const a of arr){if(types.includes(a.action_type))t+=num(a.value);}return t;}
function pickType(arr,prio){if(!Array.isArray(arr))return null;for(const t of prio){if(arr.some(a=>a.action_type===t))return t;}return null;}
function pickSum(arr,prio){const t=pickType(arr,prio);return t?actionSum(arr,[t]):0;}
function outboundClicks(d){if(Array.isArray(d.outbound_clicks))return actionSum(d.outbound_clicks,['outbound_click']);return num(d.outbound_clicks);}
function outboundCtr(d,clicks,imps){return imps?(clicks/imps)*100:0;}
function creativeKey(adName){if(!adName)return '';let k=adName.toLowerCase();k=k.replace(/^\s*(vid|pic|video|image)\s*-\s*/,'');k=k.replace(/^copy\s*\d*\s*of\s*/,'');return k.trim();}
function round(n,p){const f=10**p;return Math.round(n*f)/f;}
function flattenOne(d){const spend=num(d.spend),impressions=num(d.impressions),reach=num(d.reach);const frequency=num(d.frequency)||(reach?impressions/reach:0);const cpm=num(d.cpm)||(impressions?(spend/impressions)*1000:0);const clicks=outboundClicks(d);const ctr=outboundCtr(d,clicks,impressions);const lpv=actionSum(d.actions,CONFIG.lpv);const atc=pickSum(d.actions,CONFIG.atc);const ic=pickSum(d.actions,CONFIG.ic);const pType=pickType(d.actions,CONFIG.purchase);const purchases=pType?actionSum(d.actions,[pType]):0;const purchasesValue=(pType&&pickType(d.action_values,[pType]))?actionSum(d.action_values,[pType]):pickSum(d.action_values,CONFIG.purchase_value);const roas=spend?purchasesValue/spend:0;const aov=purchases?purchasesValue/purchases:0;const cvr=clicks?(purchases/clicks)*100:0;return{Date:d.date_start||d.date_stop||'',Ad_ID:d.ad_id||'',Ad_Name:d.ad_name||'',AdSet_Name:d.adset_name||'',Campaign_Name:d.campaign_name||'',Creative_Key:creativeKey(d.ad_name),Spend:round(spend,2),Impressions:impressions,Reach:reach,Frequency:round(frequency,2),CPM:round(cpm,2),Clicks:clicks,CTR_Pct:round(ctr,4),LPV:lpv,Adds_to_Cart:atc,Initiate_Checkout:ic,Purchases:purchases,Purchases_Value:round(purchasesValue,2),ROAS:round(roas,4),AOV:round(aov,2),Purchase_CVR_Pct:round(cvr,4),Pulled_At:new Date().toISOString()};}
const out=[];for(const item of items){const j=item.json;if(j&&j.error){out.push({json:{error:JSON.stringify(j.error)}});continue;}const rows=Array.isArray(j.data)?j.data:[];for(const row of rows){if(!row||(row.spend==null&&row.impressions==null&&!row.date_start))continue;out.push({json:flattenOne(row)});}}
if(!out.length)return[{json:{error:'No ad-level insights rows returned'}}];
return out;

const rows = items.map(i => i.json).filter(j => j && !j.error && j.Ad_ID !== undefined && j.Date);
if (!rows.length) throw new Error('No valid ad-level rows to write');
return [{ json: { rows } }];

const SHEET='Daily_Raw_Meta_Ads';
const need=['Date','Ad_ID','Ad_Name','AdSet_Name','Campaign_Name','Creative_Key','Spend','Impressions','Reach','Frequency','CPM','Clicks','CTR_Pct','LPV','Adds_to_Cart','Initiate_Checkout','Purchases','Purchases_Value','ROAS','AOV','Purchase_CVR_Pct','Pulled_At'];
function normDate(v){if(typeof v==='number'&&v>20000&&v<80000){return new Date(Date.UTC(1899,11,30)+Math.round(v)*86400000).toISOString().slice(0,10);}const s=String(v==null?'':v).trim();return /^\d{4}-\d{2}-\d{2}/.test(s)?s.slice(0,10):s;}
function normId(v){if(typeof v==='number')return v.toFixed(0);return String(v==null?'':v).trim();}
const rows=$('Collect rows').first().json.rows;
const resp=$input.first().json;
const values=Array.isArray(resp&&resp.values)?resp.values:[];
if(!values.length)throw new Error('Sheet returned no header row - not writing');
const header=values[0].map(h=>String(h).trim());
const missing=need.filter(c=>!header.includes(c));
if(missing.length)throw new Error('Header mismatch, missing: '+missing.join(', '));
if(header.length>26)throw new Error('Unexpected column count');
const iD=header.indexOf('Date'),iA=header.indexOf('Ad_ID');
const existing=new Map();let dupes=0;
for(let r=1;r<values.length;r++){const row=values[r]||[];const d=normDate(row[iD]),a=normId(row[iA]);if(!d||!a)continue;const k=d+'|'+a;if(existing.has(k))dupes++;else existing.set(k,r+1);}
const byKey=new Map();for(const row of rows){byKey.set(normDate(row.Date)+'|'+normId(row.Ad_ID),row);}
let next=values.length+1;const last=String.fromCharCode(64+header.length);
const data=[];let updated=0,appended=0;
for(const [k,row] of byKey){let n=existing.get(k);if(n)updated++;else{n=next++;appended++;}
const arr=header.map(h=>{const v=row[h];return v===undefined||v===null?'':(h==='Ad_ID'?String(v):v);});
data.push({range:"'"+SHEET+"'!A"+n+":"+last+n,values:[arr]});}
return [{json:{data,updated,appended,existing_duplicates:dupes}}];
